/* Real local photography. The build supplies a compact manifest and embeds the
   same WebP files in the portable edition. Images illustrate recipe families. */
(() => {
  const images=globalThis.MealPhotoManifest||[];
  const byFamily=new Map();
  for(const image of images){if(!byFamily.has(image.family))byFamily.set(image.family,[]);byFamily.get(image.family).push(image);}
  const hash=text=>[...String(text)].reduce((value,char)=>(value*31+char.charCodeAt(0))>>>0,0);
  const url=image=>image?(globalThis.MealEmbeddedPhotos?.[image.id]||image.path):'';
  function families(recipe) {
    const key=String(recipe.photoKey||recipe.visual||'').toLowerCase();
    const category=recipe.category||globalThis.MealEngine?.categoryOf(recipe);
    if(category==='Salades')return ['salad'];
    if(category==='Soupes')return ['soup'];
    const exact={pasta:['pasta'],noodles:['pasta'],gnocchi:['pasta'],rice:['rice'],pizza:['pizza'],salad:['salad'],soup:['soup'],fish:['fish'],salmon:['fish'],shrimp:['shrimp','fish'],chicken:['chicken'],meat:['meat'],beef:['beef','meat'],pork:['meat'],chili:['curry','meat'],burger:['burger'],omelette:['omelette'],eggs:['omelette'],gratin:['gratin'],quiche:['quiche','gratin'],toast:['toast'],wrap:['toast'],hummus:['hummus'],vegetables:['vegetables'],curry:['curry'],fruit:['fruit'],yogurt:['breakfast'],oatmeal:['breakfast'],smoothie:['fruit','breakfast'],breakfast:['breakfast'],pancakes:['pancakes','crepe'],cake:['dessert'],chocolate:['dessert'],crumble:['dessert'],pudding:['dessert'],cookies:['dessert'],dessert:['dessert']};
    if(exact[key])return exact[key];
    const title=`${recipe.id} ${recipe.title}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
    if(/soup|veloute|potage/.test(key+' '+title))return ['soup'];
    if(/salad|taboule/.test(key+' '+title))return ['salad'];
    if(/hummus|houmous/.test(key+' '+title))return ['hummus','vegetables','salad'];
    if(/pancake|crepe/.test(key+' '+title))return ['pancakes','crepe','breakfast'];
    if(/yaourt|yogurt|porridge|granola|avoine/.test(key+' '+title))return ['breakfast','fruit'];
    if(/cake|cookie|gateau|dessert|muffin|brownie|tarte.*pomme|clafouti|crumble/.test(key+' '+title))return ['dessert','pastry'];
    if(/fruit|compote/.test(key+' '+title))return ['fruit','breakfast'];
    if(/toast|tartine|croque|wrap|quesadilla/.test(key+' '+title))return ['toast','breakfast','pizza'];
    if(/\begg|\boeuf|omelette|shakshuka/.test(key+' '+title))return ['omelette','breakfast'];
    if(/pizza/.test(key+' '+title))return ['pizza'];
    if(/fish|salmon|saumon|cabillaud|poisson|crevette|thon/.test(key+' '+title))return ['fish'];
    if(/chicken|poulet|dinde/.test(key+' '+title))return ['chicken'];
    if(/burger/.test(key+' '+title))return ['burger'];
    if(/beef|boeuf|porc|sauciss|lardon|chorizo|meat/.test(key+' '+title))return ['meat','chicken'];
    if(/curry|dal|dahl/.test(key+' '+title))return ['curry','rice'];
    if(/rice|riz|risotto|biryani|quinoa|boulgour|semoule/.test(key+' '+title))return ['rice'];
    if(/gratin|quiche|tarte|lasagn/.test(key+' '+title))return ['gratin','pasta'];
    if(/pasta|pate|nouille|noodle|gnocchi/.test(key+' '+title))return ['pasta'];
    return ['vegetables','salad'];
  }
  function photoFor(recipe) {
    const overrides={'omelette-courgette':'cook-omelette-01',shakshuka:'cook-omelette-03','veloute-carottes':'cook-soup-01','curry-pois-chiches':'cook-curry-chickpea-01'};
    const exactPhoto=images.find(image=>image.id===overrides[recipe.id]);
    if(exactPhoto)return exactPhoto;
    for(const family of families(recipe)){
      const candidates=byFamily.get(family);
      if(candidates?.length)return candidates[hash(recipe.id)%candidates.length];
    }
    // A missing family is recorded by the build; no broken remote URL is used.
    return images.find(image=>image.id==='pasta-001')||images[0];
  }
  const hero=()=>url(images.find(image=>image.hero)||images.find(image=>image.id==='pasta-003')||images.find(image=>image.family==='pasta')||images[0]);
  globalThis.MealPhotos={recipe:recipe=>url(photoFor(recipe)),family:recipe=>photoFor(recipe)?.family,expectedFamilies:families,hero,count:images.length,families:()=>[...byFamily.keys()]};
})();
